def f(l, r):
    xor_result = 0
    for i in range(len(l)):
        if l[i] != r[i]:
            xor_result = (1 << (len(l) - i)) - 1
            break
    return xor_result

def main():
    n = int(input())
    l = input()
    r = input()

    result = f(l, r)
    print(bin(result)[2:].zfill(n))

if __name__ == "__main__":
    main()
